import{_ as o,o as d,c as t,a4 as a}from"./chunks/framework.CKd2nDfM.js";const u=JSON.parse('{"title":"디자인 언어","description":"Material Plus는 머터리얼 디자인 명세를 구현합니다. 누군가의 구현을 감싸는 것이 아닙니다. 이 페이지의 거의 전부가 그 결정 하나에서 나옵니다. prop이 쓰는 단어, 토큰이 담은 값, 그리고 명세를 알면서 벗어난 네 군데까지.","frontmatter":{"title":"디자인 언어","order":0},"headers":[],"relativePath":"ko/design/design-language.md","filePath":"ko/design/design-language.md","lastUpdated":1788501759000}'),c={name:"ko/design/design-language.md"};function r(l,e,i,n,s,p){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="디자인-언어" tabindex="-1">디자인 언어 <a class="header-anchor" href="#디자인-언어" aria-label="Permalink to &quot;디자인 언어&quot;">​</a></h1><p class="mp-lede">Material Plus는 머터리얼 디자인 명세를 구현합니다. 누군가의 구현을 감싸는 것이 아닙니다. 이 페이지의 거의 전부가 그 결정 하나에서 나옵니다. prop이 쓰는 단어, 토큰이 담은 값, 그리고 명세를 알면서 벗어난 네 군데까지.</p><p>규칙은 하나입니다. <strong>명세에 단어가 있으면 명세의 단어를 씁니다.</strong> 색 역할은 <code>primary</code>나 <code>on-surface-variant</code>이고, 모서리는 <code>extra-small</code>이며, 타입 역할은 <code>body-large</code>, 밀도 단계는 <code>-1</code>입니다. Material UI의 단어가 아닙니다. MUI의 팔레트는 <code>main</code>/<code>light</code>/<code>dark</code>/<code>contrastText</code>이고 그것은 더 이르고 다른 색 모델입니다. 그 이름을 빌려 오면 이 라이브러리가 구현하지 않는 시스템을 설명하게 됩니다.</p><h2 id="면" tabindex="-1">면 <a class="header-anchor" href="#면" aria-label="Permalink to &quot;면&quot;">​</a></h2><p>여기서 그려지는 모든 것은 머터리얼의 중립 면 역할 위에 있습니다. 강조 색 위가 아닙니다.</p><p>사소해 보이지만 라이브러리 전체의 인상을 결정합니다. 컨테이너는 <strong>남의</strong> 내용을 담고, 그 내용은 자기 색을 가지고 옵니다. 본문, 링크, 필드, 버튼. 강조 색으로 채운 면 위에서는 그 하나하나가 on-accent 처리를 따로 받아야 합니다. 그래서 컨테이너의 <code>variant</code> 사다리는 중립 역할을 타고 올라가고, 가장 높은 곳이 명세 자신의 filled 카드인 <code>surface-container-highest</code>입니다.</p><table tabindex="0"><thead><tr><th><code>variant</code></th><th>컨테이너가 칠하는 것</th></tr></thead><tbody><tr><td><code>filled</code></td><td><code>surface-container-highest</code></td></tr><tr><td><code>tonal</code></td><td><code>surface-container</code></td></tr><tr><td><code>elevated</code></td><td>level 1 그림자 아래의 <code>surface-container-low</code></td></tr><tr><td><code>outlined</code></td><td>칠하지 않고 <code>outline-variant</code> 실선 하나</td></tr><tr><td><code>text</code></td><td>아무것도 칠하지 않음</td></tr></tbody></table><p>같은 다섯 단어가 색칠 대상이 <strong>자기 자신</strong>인 컴포넌트에서는 다른 것을 뜻합니다. 버튼, 칩, 배지에서 <code>filled</code>는 강조 색과 그 위의 잉크입니다. 어긋난 것이 아니라 그것이 구분입니다. <code>filled</code>는 강조의 세기에 대한 진술이고, 무엇을 칠하는지는 그 컴포넌트가 주인공인지 무대인지에 달렸습니다.</p><h2 id="색은-역할이지-값이-아닙니다" tabindex="-1">색은 역할이지 값이 아닙니다 <a class="header-anchor" href="#색은-역할이지-값이-아닙니다" aria-label="Permalink to &quot;색은 역할이지 값이 아닙니다&quot;">​</a></h2><p>배색은 <strong>소스 색 하나</strong>에서 생성됩니다. 머터리얼이 하나에서 생성하는 방식 그대로입니다. <code>--mp-source-color</code>를 설정하면 모든 역할이 따라옵니다. 프로바이더도, 테마 객체도, 리렌더도 없습니다. CSS이기 때문에 페이지의 한 구역이 나머지와 달라지는 데 어느 쪽도 서로를 알 필요가 없습니다.</p><p><code>color</code>가 색이 아니라 계열을 받는 이유이자, 계열이 넷인 이유입니다. <code>primary</code>, <code>secondary</code>, <code>tertiary</code>, <code>error</code>. MD3의 색 시스템에는 <code>success</code>도 <code>info</code>도 <code>warning</code>도 없고, 그것들을 제공하는 것은 토큰 시트가 만들어 낼 방법이 없는 역할을 약속하는 일입니다. 초록이 필요한 알림은 토큰을 설정합니다. 라이브러리의 나머지가 지킬 수 없는 다섯 번째 계열을 받는 것이 아니라.</p><p>역할과 그것을 옮기는 방법은 <a href="./color">색</a>에 있습니다.</p><h2 id="크기는-명세를-넘어선-유일한-곳입니다" tabindex="-1">크기는 명세를 넘어선 유일한 곳입니다 <a class="header-anchor" href="#크기는-명세를-넘어선-유일한-곳입니다" aria-label="Permalink to &quot;크기는 명세를 넘어선 유일한 곳입니다&quot;">​</a></h2><p>머터리얼은 컴포넌트마다 크기를 하나로 정의합니다. 텍스트 필드는 56dp, 그것으로 끝입니다. 제품 전체를 위한 디자인 시스템을 기술하는 것이고, 거기서는 컨트롤마다 높이가 하나인 것이 요점이기 때문입니다.</p><p>컴포넌트 라이브러리는 디자인 시스템이 계획하지 않은 자리에 쓰입니다. 필터 바, 표 안의 인라인 편집기, 빽빽한 설정 페이지, 마케팅 히어로. 그런 자리에는 사다리가 필요하고, 라이브러리에서 얻지 못한 사람은 <code>!important</code>로 만들어 냅니다.</p><p>그래서 단이 다섯이고 <strong><code>md</code>가 명세의 것</strong>입니다.</p><table tabindex="0"><thead><tr><th><code>size</code></th><th>컨트롤 높이</th></tr></thead><tbody><tr><td><code>xs</code></td><td>32px</td></tr><tr><td><code>sm</code></td><td>40px</td></tr><tr><td><code>md</code></td><td>56px — MD3 자신의</td></tr><tr><td><code>lg</code></td><td>64px</td></tr><tr><td><code>xl</code></td><td>72px</td></tr></tbody></table><p>사다리는 명세의 값에서 시작하지 않고 그 값을 가운데 둡니다. 요령이 거기 있습니다. 아무 말도 하지 않으면 <code>md</code>가 나오므로, 이 사다리가 있다는 것을 몰라도 머터리얼의 크기를 받습니다. <code>xs</code>와 <code>xl</code>은 그냥 더 작고 더 큰 것이 아니라 쓸 수 있는 범위의 양 끝입니다. <code>xs</code> 아래에서는 컨트롤이 24px 터치 대상이 되지 못합니다. 여섯 번째 단은 없습니다. 그만큼 긴 사다리가 필요하다면 호출하는 쪽이 원하는 것은 맞춤 컨트롤입니다.</p><h2 id="밀도는-두-번째-축이지-더-긴-사다리가-아닙니다" tabindex="-1">밀도는 두 번째 축이지 더 긴 사다리가 아닙니다 <a class="header-anchor" href="#밀도는-두-번째-축이지-더-긴-사다리가-아닙니다" aria-label="Permalink to &quot;밀도는 두 번째 축이지 더 긴 사다리가 아닙니다&quot;">​</a></h2><p><code>size</code>는 이것이 어떤 컨트롤인지를 고릅니다. <a href="./prop-conventions#density"><code>density</code></a>는 고른 것에서 여백을 덜어냅니다. 머터리얼 자신의 척도인 <code>0</code>에서 <code>-3</code>까지, 한 단계에 4px이고, <strong>여백만</strong> 덜어냅니다. 타입 스케일은 움직이지 않습니다.</p><p>둘을 하나로 합칠 수 없습니다. 리스트의 <code>size=&quot;sm&quot;</code>은 작은 리스트이고, <code>density={-2}</code>는 화면에 더 많이 들어간 보통 리스트입니다. 조밀한 화면이 원하는 것은 두 번째입니다. 읽을 수 있던 크기 그대로 행이 더 많이. 그걸 위해 글자를 줄이면 볼 것이 많아진 바로 그 순간에 읽기 어려워집니다.</p><p>담는 컴포넌트만 이 축을 받고, 각 단계는 크기 사다리가 이미 이름을 가진 높이에 내려앉습니다. 조밀한 리스트와 그 옆의 버튼이 여전히 맞는 것이 그 때문입니다.</p><h2 id="높이는-색조를-데리고-움직입니다" tabindex="-1">높이는 색조를 데리고 움직입니다 <a class="header-anchor" href="#높이는-색조를-데리고-움직입니다" aria-label="Permalink to &quot;높이는 색조를 데리고 움직입니다&quot;">​</a></h2><p><a href="./prop-conventions#elevation"><code>elevation</code></a>은 면 역할 <strong>과</strong> 그림자이지 둘 중 하나가 아닙니다. MD3는 높이를 자유로운 축으로 다루지 않습니다. elevated 면은 level 1 그림자 아래의 <code>surface-container-low</code>이고, 둘은 하나의 결정입니다. 그림자만 드리우는 prop은 <code>filled</code> 상자를 명세가 이름을 갖지 않은 면으로 띄웁니다.</p><p>그림자는 명세 자신의 두 겹 조합입니다. 좁은 key 그림자와 넓은 ambient 그림자. 흐린 상자 하나가 아닙니다. 그 짝이 있어야 떠 있는 면이 스티커에 후광이 진 것이 아니라 위에서 빛을 받은 것으로 읽힙니다.</p><h2 id="모서리는-그것이-어떤-물건인지를-말합니다" tabindex="-1">모서리는 그것이 어떤 물건인지를 말합니다 <a class="header-anchor" href="#모서리는-그것이-어떤-물건인지를-말합니다" aria-label="Permalink to &quot;모서리는 그것이 어떤 물건인지를 말합니다&quot;">​</a></h2><p>반경은 취향에 맞추는 크기가 아닙니다. 머터리얼에서 이것은 그 물건이 <strong>무엇인지</strong>에 대한 진술이므로 <code>size</code>를 따라 움직이지 않습니다.</p><ul><li><code>extra-small</code>, 4px — 리스트의 행, 메뉴의 항목.</li><li><code>medium</code>, 12px — 시트. 박스와 카드는 어느 단에서나 <code>corner-medium</code>입니다.</li><li><code>extra-large</code>, 28px — 다이얼로그. 페이지를 차지한 시트는 패널이 아니라 물건처럼 보여도 됩니다.</li><li><code>full</code> — 알약. 버튼, 칩, 트랙.</li></ul><h2 id="상태는-겹이지-두-번째-색이-아닙니다" tabindex="-1">상태는 겹이지 두 번째 색이 아닙니다 <a class="header-anchor" href="#상태는-겹이지-두-번째-색이-아닙니다" aria-label="Permalink to &quot;상태는 겹이지 두 번째 색이 아닙니다&quot;">​</a></h2><p>호버와 포커스와 누름은 <strong>내용</strong> 색을 컨테이너 위에 반투명하게 씌운 것입니다. 호버 8%, 포커스와 누름 10%. 규칙 하나가 filled 버튼과 outlined 버튼과 맨 text 버튼을 모두 덮고, 어느 것도 두 번째 배경을 지목하지 않습니다.</p><p><code>hover:bg-…</code>가 아니라 겹이어야 하는 이유는 배경은 대체밖에 안 되기 때문입니다. 대체하기 때문에 text 버튼의 호버가 불투명해지고 outlined 버튼의 호버가 자기 테두리를 덮습니다. 겹은 합성하므로 아래에 있던 것 — 채움이든 실선이든 아무것도 아니든 — 이 그대로 비칩니다.</p><h2 id="모션은-토큰이고-방향을-가집니다" tabindex="-1">모션은 토큰이고, 방향을 가집니다 <a class="header-anchor" href="#모션은-토큰이고-방향을-가집니다" aria-label="Permalink to &quot;모션은 토큰이고, 방향을 가집니다&quot;">​</a></h2><p>모든 지속 시간과 곡선이 custom property입니다. 페이지 전체를 조금 느리게 하고 싶으면 값 하나를 바꿉니다. <code>MPEasing</code>은 명세의 이름만 받고 임의의 <code>cubic-bezier()</code>는 받지 않습니다. <code>color</code>가 계열을 받는 것과 같은 이유입니다. 한 컴포넌트의 prop에 적힌 곡선은 테마가 닿을 수 없는 곡선입니다.</p><p>짝은 머터리얼이 전환을 기술하는 방식이지 서로 바꿔 쓸 수 있는 네 선택지가 아닙니다. <strong>도착하는</strong> 것은 감속하며 제자리에 들어오고, <strong>떠나는</strong> 것은 가속하며 비켜납니다. 그 비대칭이 기본값에 들어 있어서, 숫자를 몰라도 나가는 것이 들어오는 것보다 빠릅니다.</p><p><code>prefers-reduced-motion</code>은 컴포넌트에서도 스타일시트에서도 어디서나 존중되고, 이를 위한 prop은 없습니다.</p><h2 id="함께-삽니다" tabindex="-1">함께 삽니다 <a class="header-anchor" href="#함께-삽니다" aria-label="Permalink to &quot;함께 삽니다&quot;">​</a></h2><p>여기에는 페이지 수준의 것이 없습니다. 리셋도, 프로바이더도, 전역 스타일도 없습니다. 그리고 페이지에 <code>--md-sys-color-*</code> 토큰이 이미 있으면 컴포넌트가 그것을 읽으므로, 이미 머터리얼을 쓰는 프로젝트는 자기 설정을 그대로 유지합니다.</p><p>혼자 보면 이상해 보이는 결정 몇 개가 여기서 나옵니다. 모든 컨트롤이 <code>box-sizing</code>을 명시적으로 씁니다. 페이지 리셋이 없으면 outlined 상자의 실선이 여백 바깥에 붙어서 옆의 filled 상자보다 2px 넓게 나오기 때문입니다. <code>&lt;ul role=&quot;list&quot;&gt;</code>를 소리 내어 말합니다. 호스트의 리셋이 불릿을 없앨 수 있고 사파리는 그때 리스트 의미까지 함께 없애기 때문입니다. 표의 여백은 인라인입니다. <code>.prose td</code>와 <code>.vp-doc td</code>가 태그 이름으로 셀을 스타일하고, 그 구체성은 유틸리티가 이길 수 없기 때문입니다.</p><p>페이지를 자기가 소유한다고 가정하는 컴포넌트 라이브러리에는 이 중 어느 것도 필요 없습니다. 이 라이브러리는 그렇게 가정하지 않습니다.</p><h2 id="다음" tabindex="-1">다음 <a class="header-anchor" href="#다음" aria-label="Permalink to &quot;다음&quot;">​</a></h2><ul><li><a href="./color">색</a> — 역할과 테마 적용 방법.</li><li><a href="./prop-conventions">Prop 규약</a> — 공유 어휘를 축별로.</li><li><a href="./breakpoints">브레이크포인트</a> — 모든 것이 다시 흐르는 윈도우 크기 클래스.</li></ul>',41)])])}const g=o(c,[["render",r]]);export{u as __pageData,g as default};
